CREATE TABLE IF NOT EXISTS lattis_role (id varchar(191) PRIMARY KEY, description text NOT NULL);
CREATE TABLE IF NOT EXISTS lattis_role_grant (role_id varchar(191) NOT NULL, action varchar(191) NOT NULL, resource_type varchar(191) NOT NULL, PRIMARY KEY (role_id,action,resource_type), FOREIGN KEY (role_id) REFERENCES lattis_role(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS lattis_user_role (user_id varchar(191) NOT NULL, role_id varchar(191) NOT NULL, resource_id varchar(191) NOT NULL DEFAULT '*', PRIMARY KEY (user_id,role_id,resource_id), FOREIGN KEY (role_id) REFERENCES lattis_role(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS lattis_secret_ref (name varchar(191) PRIMARY KEY, provider varchar(191) NOT NULL, locator text NOT NULL, allowed_package varchar(191) NOT NULL, created_at datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3));
CREATE TABLE IF NOT EXISTS lattis_service_token (id char(36) PRIMARY KEY, name varchar(191) NOT NULL, token_hash char(64) NOT NULL UNIQUE, scopes json NOT NULL, expires_at datetime(3) NOT NULL, revoked_at datetime(3) NULL);
CREATE TABLE IF NOT EXISTS lattis_audit (id bigint unsigned NOT NULL AUTO_INCREMENT PRIMARY KEY, at datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), actor varchar(191) NOT NULL, action varchar(191) NOT NULL, resource varchar(191) NOT NULL, result varchar(191) NOT NULL, correlation_id varchar(191) NOT NULL);
CREATE TABLE IF NOT EXISTS lattis_immudb_outbox (audit_id bigint unsigned PRIMARY KEY, exported_at datetime(3) NULL, digest char(64) NULL, KEY lattis_immudb_outbox_pending (exported_at,audit_id), FOREIGN KEY (audit_id) REFERENCES lattis_audit(id));
CREATE TRIGGER IF NOT EXISTS lattis_audit_immudb_outbox AFTER INSERT ON lattis_audit FOR EACH ROW INSERT INTO lattis_immudb_outbox(audit_id) VALUES (NEW.id);
INSERT IGNORE INTO lattis_immudb_outbox(audit_id) SELECT id FROM lattis_audit;
CREATE TABLE IF NOT EXISTS lattis_module (name varchar(191) PRIMARY KEY, version varchar(191) NOT NULL, digest varchar(191) NOT NULL, kind varchar(20) NOT NULL CHECK (kind IN ('node','shard')), installed_at datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3));
CREATE TABLE IF NOT EXISTS lattis_node_receipt (node_name varchar(191) NOT NULL, principal_id varchar(191) NOT NULL, idempotency_key varchar(128) NOT NULL, request_digest char(64) NOT NULL, response json NOT NULL, PRIMARY KEY (node_name,principal_id,idempotency_key));
INSERT IGNORE INTO lattis_role (id,description) VALUES ('owner','Instance owner');
INSERT IGNORE INTO lattis_role_grant (role_id,action,resource_type) VALUES ('owner','*','*');
CREATE TABLE IF NOT EXISTS lattis_content_type (type_key varchar(191) PRIMARY KEY, label varchar(191) NOT NULL, fields json NOT NULL, created_at datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), updated_at datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3));
CREATE TABLE IF NOT EXISTS lattis_content (id char(36) PRIMARY KEY, type_key varchar(191) NOT NULL, slug varchar(191) NOT NULL, title text NOT NULL, body longtext NOT NULL, excerpt text NOT NULL, status varchar(20) NOT NULL CHECK (status IN ('draft','published','archived')), data json NOT NULL, revision int NOT NULL DEFAULT 1, published_at datetime(3) NULL, created_at datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), updated_at datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), UNIQUE KEY lattis_content_slug (type_key,slug), FOREIGN KEY (type_key) REFERENCES lattis_content_type(type_key));
CREATE TABLE IF NOT EXISTS lattis_content_link (id char(36) PRIMARY KEY, source_id char(36) NOT NULL, relation varchar(191) NOT NULL, target_kind varchar(20) NOT NULL CHECK (target_kind IN ('content','node','shard','media','external')), target_ref varchar(191) NOT NULL, position int NOT NULL DEFAULT 0, UNIQUE KEY lattis_content_link_unique (source_id,relation,target_kind,target_ref), KEY lattis_content_link_target (target_kind,target_ref), FOREIGN KEY (source_id) REFERENCES lattis_content(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS lattis_taxonomy_term (id char(36) PRIMARY KEY, taxonomy varchar(191) NOT NULL, slug varchar(191) NOT NULL, label varchar(191) NOT NULL, parent_id char(36) NULL, source_system varchar(80) NULL, source_site varchar(191) NULL, external_id varchar(191) NULL, UNIQUE KEY lattis_term_slug (taxonomy,slug), UNIQUE KEY lattis_term_source (source_system,source_site,taxonomy,external_id), FOREIGN KEY (parent_id) REFERENCES lattis_taxonomy_term(id));
CREATE TABLE IF NOT EXISTS lattis_content_term (content_id char(36) NOT NULL, term_id char(36) NOT NULL, PRIMARY KEY (content_id,term_id), FOREIGN KEY (content_id) REFERENCES lattis_content(id) ON DELETE CASCADE, FOREIGN KEY (term_id) REFERENCES lattis_taxonomy_term(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS lattis_media (id char(36) PRIMARY KEY, storage_ref text NOT NULL, mime_type varchar(191) NOT NULL, alt_text text NOT NULL, metadata json NOT NULL, content_sha256 char(64) NULL, byte_count bigint NULL, source_system varchar(80) NULL, source_site varchar(191) NULL, external_id varchar(191) NULL, created_at datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), UNIQUE KEY lattis_media_source (source_system,source_site,external_id));
ALTER TABLE lattis_media ADD COLUMN IF NOT EXISTS content_sha256 char(64) NULL;
ALTER TABLE lattis_media ADD COLUMN IF NOT EXISTS byte_count bigint NULL;
CREATE TABLE IF NOT EXISTS lattis_content_source (source_system varchar(80) NOT NULL, source_site varchar(191) NOT NULL, source_kind varchar(80) NOT NULL, external_id varchar(191) NOT NULL, content_id char(36) NOT NULL, source_digest char(64) NOT NULL, imported_at datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), PRIMARY KEY (source_system,source_site,source_kind,external_id), FOREIGN KEY (content_id) REFERENCES lattis_content(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS lattis_import_cursor (source_system varchar(80) NOT NULL, source_site varchar(191) NOT NULL, import_key varchar(191) NOT NULL, cursor_value varchar(191) NULL, batch_digest char(64) NOT NULL, updated_at datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), PRIMARY KEY (source_system,source_site,import_key));
CREATE TABLE IF NOT EXISTS lattis_import_user (id char(36) PRIMARY KEY, source_site varchar(191) NOT NULL, external_id varchar(191) NOT NULL, email varchar(191) NOT NULL, display_name varchar(191) NOT NULL, source_roles json NOT NULL, claimed_user_id varchar(191) NULL, auth_mode varchar(20) NOT NULL DEFAULT 'verified-email' CHECK (auth_mode IN ('verified-email','password')), legacy_password_ciphertext text NULL, password_claimed_at datetime(3) NULL, created_at datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), updated_at datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), UNIQUE KEY lattis_import_user_source (source_site,external_id), KEY lattis_import_user_email (email), KEY lattis_import_user_claimed (claimed_user_id));
ALTER TABLE lattis_import_user ADD COLUMN IF NOT EXISTS legacy_password_ciphertext text NULL;
ALTER TABLE lattis_import_user ADD COLUMN IF NOT EXISTS password_claimed_at datetime(3) NULL;
ALTER TABLE lattis_import_user ADD COLUMN IF NOT EXISTS auth_mode varchar(20) NOT NULL DEFAULT 'verified-email';
CREATE INDEX IF NOT EXISTS lattis_import_user_claimed ON lattis_import_user(claimed_user_id);
CREATE TABLE IF NOT EXISTS lattis_video (id char(36) PRIMARY KEY, title varchar(500) NOT NULL, mime_type varchar(40) NOT NULL CHECK (mime_type = 'video/mp4'), byte_count bigint NOT NULL CHECK (byte_count > 0), content_sha256 char(64) NOT NULL, storage_ref varchar(100) NULL, state varchar(20) NOT NULL CHECK (state IN ('pending','ready')), download_ui varchar(10) NOT NULL CHECK (download_ui IN ('show','hide')), protection_mode varchar(30) NOT NULL CHECK (protection_mode IN ('access-controlled','drm-required')), watermark_mode varchar(30) NOT NULL CHECK (watermark_mode IN ('off','forensic-required')), created_by varchar(191) NOT NULL, created_at datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), updated_at datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3));
CREATE TABLE IF NOT EXISTS lattis_video_playback (id char(36) PRIMARY KEY, video_id char(36) NOT NULL, user_id varchar(191) NOT NULL, viewer_ciphertext text NOT NULL, started_at datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), expires_at datetime(3) NOT NULL, KEY lattis_video_playback_user (user_id,expires_at), KEY lattis_video_playback_expiry (expires_at), FOREIGN KEY (video_id) REFERENCES lattis_video(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS lattis_video_package (id char(36) PRIMARY KEY, video_id char(36) NOT NULL, container_format varchar(10) NOT NULL CHECK (container_format = 'cmaf'), protection varchar(10) NOT NULL CHECK (protection IN ('clear','drm')), encryption_scheme varchar(10) NULL CHECK (encryption_scheme IN ('cenc','cbcs')), watermark varchar(10) NOT NULL CHECK (watermark IN ('off','forensic')), drm_provider_ref varchar(191) NULL, watermark_provider_ref varchar(191) NULL, storage_ref varchar(100) NOT NULL, state varchar(10) NOT NULL CHECK (state IN ('ready','failed')), created_at datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), KEY lattis_video_package_video (video_id,state,created_at), FOREIGN KEY (video_id) REFERENCES lattis_video(id) ON DELETE CASCADE, CHECK ((protection = 'clear' AND encryption_scheme IS NULL AND drm_provider_ref IS NULL) OR (protection = 'drm' AND encryption_scheme IS NOT NULL AND drm_provider_ref IS NOT NULL)), CHECK ((watermark = 'off' AND watermark_provider_ref IS NULL) OR (watermark = 'forensic' AND watermark_provider_ref IS NOT NULL)));
CREATE TABLE IF NOT EXISTS lattis_content_author (content_id char(36) PRIMARY KEY, import_user_id char(36) NOT NULL, FOREIGN KEY (content_id) REFERENCES lattis_content(id) ON DELETE CASCADE, FOREIGN KEY (import_user_id) REFERENCES lattis_import_user(id));
